package org.securemail.identity;

import org.junit.jupiter.api.*;
import org.junit.jupiter.api.io.TempDir;
import org.securemail.ecosystem.protocol.*;
import org.securemail.ecosystem.protocol.IdentityProtocol.*;
import java.nio.file.*;
import java.security.*;
import java.time.*;
import java.util.*;
import java.util.concurrent.*;
import static org.junit.jupiter.api.Assertions.*;

class IdentityStoreTest {
    @TempDir Path home;
    MutableClock clock;KeyPair service,root,device,recovery,app;IdentityStore store;String account,deviceId;IdentityStore.Session session;byte[] audit;
    static KeyPair pair()throws GeneralSecurityException{return KeyPairGenerator.getInstance("Ed25519").generateKeyPair();}
    static byte[] key(KeyPair pair){return pair.getPublic().getEncoded();}
    @BeforeEach void setup()throws Exception{clock=new MutableClock();service=pair();root=pair();device=pair();recovery=pair();app=pair();audit=new byte[32];new SecureRandom().nextBytes(audit);store=new IdentityStore(home.resolve("identity.db"),service,audit,clock);account=IdentityProtocol.id(key(root));deviceId=IdentityProtocol.id(key(device));session=register(root,device,recovery);}
    @AfterEach void close()throws Exception{store.close();}
    IdentityStore.Session register(KeyPair root,KeyPair device,KeyPair recovery){String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.registration(store.audience(),key(root),key(device),key(recovery),"Николай",clock.millis(),nonce);return store.register(key(root),key(device),key(recovery),"Николай",clock.millis(),nonce,IdentityProtocol.sign(root.getPrivate(),body),IdentityProtocol.sign(device.getPrivate(),body));}
    Capability cap(App target,Set<Scope> scopes){String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.capabilityRequest(store.audience(),account,deviceId,session.generation(),target,key(app),scopes,600000,clock.millis(),nonce);return store.issueCapability(account,deviceId,session.generation(),target,key(app),scopes,600000,clock.millis(),nonce,IdentityProtocol.sign(device.getPrivate(),body),IdentityProtocol.sign(app.getPrivate(),body));}
    void step(){IdentityStore.Challenge c=store.stepUpChallenge(account,deviceId,session.generation());byte[] b=IdentityProtocol.stepUp(store.audience(),account,deviceId,c.challenge(),c.expiresAt());store.stepUp(account,deviceId,session.generation(),c.challenge(),IdentityProtocol.sign(root.getPrivate(),b),IdentityProtocol.sign(device.getPrivate(),b));}
    KeyPair enroll()throws Exception {KeyPair next=pair();String nonce=IdentityProtocol.nonce();byte[] request=IdentityProtocol.login(store.audience(),account,IdentityProtocol.id(key(next)),clock.millis(),nonce);IdentityStore.DeviceChallenge c=store.challengeDevice(account,key(next),clock.millis(),nonce,IdentityProtocol.sign(next.getPrivate(),request));step();store.approveDevice(account,deviceId,session.generation(),c.challenge(),IdentityProtocol.sign(device.getPrivate(),IdentityProtocol.deviceApproval(store.audience(),account,deviceId,c.challenge(),key(next),c.expiresAt())));return next;}
    IdentityStore.Session login(KeyPair selected){String nonce=IdentityProtocol.nonce(),id=IdentityProtocol.id(key(selected));return store.login(account,id,clock.millis(),nonce,IdentityProtocol.sign(selected.getPrivate(),IdentityProtocol.login(store.audience(),account,id,clock.millis(),nonce)));}
    void bootstrap(){IdentityStore.OwnerChallenge c=store.ownerChallenge(account);store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),account,c.challenge(),c.expiresAt())));}
    @Test void registrationPreservesLegacyIdWithoutExportAndOnlyTwoSystemRoles(){assertEquals(account,session.accountId());assertEquals(1,session.generation());Map<String,Object> profile=store.profile(account);assertEquals("Обычный пользователь",profile.get("systemRole"));assertEquals(false,profile.get("ownerBadge"));assertTrue(store.verifyAudit());}
    @Test void registrationRequiresBothAccountAndDeviceOwnership()throws Exception {KeyPair other=pair(),newDevice=pair();String n=IdentityProtocol.nonce();byte[] b=IdentityProtocol.registration(store.audience(),key(other),key(newDevice),key(recovery),"Тест",clock.millis(),n);assertThrows(IdentityException.class,()->store.register(key(other),key(newDevice),key(recovery),"Тест",clock.millis(),n,IdentityProtocol.sign(root.getPrivate(),b),IdentityProtocol.sign(newDevice.getPrivate(),b)));assertThrows(IdentityException.class,()->store.register(key(other),key(newDevice),key(recovery),"Тест",clock.millis(),n,IdentityProtocol.sign(other.getPrivate(),b),IdentityProtocol.sign(device.getPrivate(),b)));}
    @Test void duplicateRegistrationCannotResetRecoveryOrTrust(){assertThrows(IdentityException.class,()->register(root,device,recovery));assertEquals(1,session.generation());}
    @Test void capabilityIsNarrowAppAndProofBound(){Capability c=cap(App.LIBRARY,EnumSet.of(Scope.LIBRARY_READ));String n=IdentityProtocol.nonce();byte[] b="document-id".getBytes(java.nio.charset.StandardCharsets.UTF_8);byte[] proof=IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(c,"library.read",b,clock.millis(),n));assertEquals(account,store.authorize(c,"library.read",b,clock.millis(),n,proof).accountId);assertThrows(IdentityException.class,()->store.authorize(c,"library.write",b,clock.millis(),IdentityProtocol.nonce(),proof));assertThrows(IllegalArgumentException.class,()->cap(App.LIBRARY,EnumSet.of(Scope.MAIL_READ)));}
    @Test void replayRejectedAndDigestDomainCannotBeReusedAsBodyProof(){Capability c=cap(App.MAIL,EnumSet.of(Scope.MAIL_SEND));String n=IdentityProtocol.nonce();byte[] b=new byte[]{1,2,3};byte[] signature=IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(c,"mail.send",b,clock.millis(),n));store.authorize(c,"mail.send",b,clock.millis(),n,signature);assertEquals("REPLAY",assertThrows(IdentityException.class,()->store.authorize(c,"mail.send",b,clock.millis(),n,signature)).code());String n2=IdentityProtocol.nonce();byte[] digest=IdentityProtocol.digest(b),sig=IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.requestDigest(c,"attachments.write",digest,clock.millis(),n2));assertThrows(IdentityException.class,()->store.authorize(c,"attachments.write",digest,clock.millis(),n2,sig));assertEquals(account,store.authorizeDigest(c,"attachments.write",digest,clock.millis(),n2,sig).accountId);}
    @Test void generationRevokesAllOldTokensAndOldTrustedDeviceCannotUseNewGeneration()throws Exception {Capability c=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));KeyPair next=enroll();IdentityStore.Session nextSession=login(next);assertEquals(2,nextSession.generation());assertFalse(store.isActive(c));String n=IdentityProtocol.nonce();byte[] request=IdentityProtocol.capabilityRequest(store.audience(),account,deviceId,nextSession.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n);assertThrows(IdentityException.class,()->store.issueCapability(account,deviceId,nextSession.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n,IdentityProtocol.sign(device.getPrivate(),request),IdentityProtocol.sign(app.getPrivate(),request)));}
    @Test void unknownDeviceCannotLoginAndEnrollmentNeedsFreshStepUp()throws Exception {KeyPair unknown=pair();assertThrows(IdentityException.class,()->login(unknown));String n=IdentityProtocol.nonce();byte[] req=IdentityProtocol.login(store.audience(),account,IdentityProtocol.id(key(unknown)),clock.millis(),n);IdentityStore.DeviceChallenge c=store.challengeDevice(account,key(unknown),clock.millis(),n,IdentityProtocol.sign(unknown.getPrivate(),req));assertEquals("REAUTH_REQUIRED",assertThrows(IdentityException.class,()->store.approveDevice(account,deviceId,session.generation(),c.challenge(),IdentityProtocol.sign(device.getPrivate(),IdentityProtocol.deviceApproval(store.audience(),account,deviceId,c.challenge(),key(unknown),c.expiresAt())))).code());}
    @Test void loginRaceOnlyOneGenerationActiveAcrossIndependentConnections()throws Exception {KeyPair next=enroll();try(IdentityStore second=new IdentityStore(home.resolve("identity.db"),service,audit,clock)){ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);Callable<IdentityStore.Session> first=()->{start.await();return login(device);};Callable<IdentityStore.Session> other=()->{start.await();String n=IdentityProtocol.nonce(),id=IdentityProtocol.id(key(next));return second.login(account,id,clock.millis(),n,IdentityProtocol.sign(next.getPrivate(),IdentityProtocol.login(store.audience(),account,id,clock.millis(),n)));};Future<IdentityStore.Session>a=pool.submit(first),b=pool.submit(other);start.countDown();IdentityStore.Session sa=a.get(5,TimeUnit.SECONDS),sb=b.get(5,TimeUnit.SECONDS);assertEquals(Set.of(2L,3L),Set.of(sa.generation(),sb.generation()));IdentityStore.Session old=sa.generation()<sb.generation()?sa:sb;KeyPair oldKey=old.deviceId().equals(deviceId)?device:next;String n=IdentityProtocol.nonce();byte[] req=IdentityProtocol.capabilityRequest(store.audience(),account,old.deviceId(),old.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n);assertThrows(IdentityException.class,()->store.issueCapability(account,old.deviceId(),old.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n,IdentityProtocol.sign(oldKey.getPrivate(),req),IdentityProtocol.sign(app.getPrivate(),req)));assertTrue(store.verifyAudit());}finally{pool.shutdownNow();}}}
    @Test void ownerBootstrapOneUseBoundToExistingAccountProofAndService(){IdentityStore.OwnerChallenge c=store.ownerChallenge(account);byte[] b=IdentityProtocol.ownerBootstrap(store.audience(),account,c.challenge(),c.expiresAt());assertThrows(IdentityException.class,()->store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(device.getPrivate(),b)));store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),b));assertEquals(true,store.profile(account).get("ownerBadge"));assertEquals("INITIALIZED",assertThrows(IdentityException.class,()->store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),b))).code());assertEquals("INITIALIZED",assertThrows(IdentityException.class,()->store.ownerChallenge(account)).code());}
    @Test void ownerBootstrapRaceAtomicAcrossConnections()throws Exception {KeyPair otherRoot=pair(),otherDevice=pair();IdentityStore.Session other=register(otherRoot,otherDevice,pair());IdentityStore.OwnerChallenge ca=store.ownerChallenge(account),cb=store.ownerChallenge(other.accountId());try(IdentityStore second=new IdentityStore(home.resolve("identity.db"),service,audit,clock)){ExecutorService pool=Executors.newFixedThreadPool(2);try{CountDownLatch start=new CountDownLatch(1);Future<Boolean>a=pool.submit(()->{start.await();try{store.bootstrapOwner(account,ca.challenge(),IdentityProtocol.sign(root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),account,ca.challenge(),ca.expiresAt())));return true;}catch(IdentityException denied){return false;}});Future<Boolean>b=pool.submit(()->{start.await();try{second.bootstrapOwner(other.accountId(),cb.challenge(),IdentityProtocol.sign(otherRoot.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),other.accountId(),cb.challenge(),cb.expiresAt())));return true;}catch(IdentityException denied){return false;}});start.countDown();assertNotEquals(a.get(5,TimeUnit.SECONDS),b.get(5,TimeUnit.SECONDS));assertTrue(store.verifyAudit());}finally{pool.shutdownNow();}}}
    @Test void expiredOwnerChallengeAndStepUpCannotBeReplayed(){IdentityStore.OwnerChallenge c=store.ownerChallenge(account);clock.value+=300001;assertThrows(IdentityException.class,()->store.bootstrapOwner(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),IdentityProtocol.ownerBootstrap(store.audience(),account,c.challenge(),c.expiresAt()))));step();clock.value+=120001;assertThrows(IdentityException.class,()->cap(App.AEGIS,EnumSet.of(Scope.ADMIN)));}
    @Test void recoveryNeedsSeparateRootAndRecoveryProofAndInvalidatesPriorDevices()throws Exception {bootstrap();KeyPair next=pair();String n=IdentityProtocol.nonce();IdentityStore.DeviceChallenge c=store.challengeDevice(account,key(next),clock.millis(),n,IdentityProtocol.sign(next.getPrivate(),IdentityProtocol.login(store.audience(),account,IdentityProtocol.id(key(next)),clock.millis(),n)));byte[] body=IdentityProtocol.recovery(store.audience(),account,c.challenge(),key(next),c.expiresAt());assertThrows(IdentityException.class,()->store.recoverDevice(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),body),IdentityProtocol.sign(root.getPrivate(),body)));store.recoverDevice(account,c.challenge(),IdentityProtocol.sign(root.getPrivate(),body),IdentityProtocol.sign(recovery.getPrivate(),body));assertThrows(IdentityException.class,()->login(device));IdentityStore.Session replacement=login(next);assertTrue(replacement.generation()>session.generation());assertEquals(true,store.profile(account).get("sensitiveRecoveryPending"));device=next;deviceId=IdentityProtocol.id(key(next));session=replacement;app=pair();assertThrows(IdentityException.class,()->cap(App.LIBRARY,EnumSet.of(Scope.LIBRARY_READ)));}
    @Test void ownerAdminRequiresStepUpWhileOrdinaryBadgeDoesNotImplyAdmin(){assertThrows(IdentityException.class,()->cap(App.AEGIS,EnumSet.of(Scope.ADMIN)));bootstrap();assertThrows(IdentityException.class,()->cap(App.AEGIS,EnumSet.of(Scope.ADMIN)));step();Capability c=cap(App.AEGIS,EnumSet.of(Scope.ADMIN));String n=IdentityProtocol.nonce();byte[] release=IdentityProtocol.digest(new byte[]{7});assertTrue(store.ownerReleaseApproval(c,release,clock.millis(),n,IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(c,"admin.execute",release,clock.millis(),n))));}
    @Test void clockRollbackFailsClosedAndCannotExtendSignedLease(){Capability c=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));clock.value+=10000;assertTrue(store.isActive(c));clock.value-=9999;assertFalse(store.isActive(c));assertEquals("CLOCK_ROLLBACK",assertThrows(IdentityException.class,()->login(device)).code());}
    @Test void capabilityCodecCanonicalAndExpiryAndTamperSafe()throws Exception {Capability c=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));String wire=IdentityProtocol.encodeCapability(c);Capability decoded=IdentityProtocol.decodeCapability(wire);assertEquals(wire,IdentityProtocol.encodeCapability(decoded));assertTrue(IdentityProtocol.verifyCapability(decoded,key(service),clock.millis()));byte[] altered=decoded.serverSignature.clone();altered[0]^=1;assertFalse(IdentityProtocol.verifyCapability(decoded.signed(altered),key(service),clock.millis()));assertFalse(IdentityProtocol.verifyCapability(decoded,key(pair()),clock.millis()));assertFalse(IdentityProtocol.verifyCapability(decoded,key(service),decoded.expiresAt));assertThrows(IllegalArgumentException.class,()->IdentityProtocol.decodeCapability(wire+"="));}
    @Test void offlineLeaseUsesMonotonicTimeRejectsClockRollbackAndAlwaysDeniesClosedData(){Capability c=cap(App.LIBRARY,EnumSet.of(Scope.LIBRARY_READ));OfflineLeaseGuard guard=new OfflineLeaseGuard(c,key(service),clock.millis(),9000,100,8999);assertTrue(guard.allows(10000,1100,9000,false));assertFalse(guard.allows(9999,1200,10000,false));assertFalse(guard.allows(10000,1200,10000,true));assertFalse(guard.allows(10000,100+600000,10000,false));assertThrows(IllegalArgumentException.class,()->new OfflineLeaseGuard(c,key(service),clock.millis(),9000,100,10000));}
    @Test void configuredServiceIdentityCannotBeSilentlyReplaced()throws Exception {assertThrows(IdentityException.class,()->new IdentityStore(home.resolve("identity.db"),pair(),audit,clock));}
    @Test void tamperedAuditBlocksReopen()throws Exception {store.close();try(java.sql.Connection sql=java.sql.DriverManager.getConnection("jdbc:sqlite:"+home.resolve("identity.db"));java.sql.Statement s=sql.createStatement()){s.executeUpdate("UPDATE audit SET target='forged' WHERE seq=1");}assertThrows(IdentityException.class,()->new IdentityStore(home.resolve("identity.db"),service,audit,clock));store=new IdentityStore(home.resolve("fresh.db"),service,audit,clock);}
    @Test void rootDeviceRecoveryAndApplicationKeysCannotBeReusedAcrossDomains()throws Exception {assertThrows(IllegalArgumentException.class,()->IdentityProtocol.registration(store.audience(),key(root),key(root),key(recovery),"Тест",clock.millis(),IdentityProtocol.nonce()));cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));assertThrows(IdentityException.class,()->cap(App.GLAS,EnumSet.of(Scope.VOICE_CALL)));String n=IdentityProtocol.nonce();byte[] req=IdentityProtocol.login(store.audience(),account,account,clock.millis(),n);assertThrows(IdentityException.class,()->store.challengeDevice(account,key(root),clock.millis(),n,IdentityProtocol.sign(root.getPrivate(),req)));}
    @Test void rotatingApplicationProofKeyRevokesPriorTokensOfThatApplication()throws Exception {Capability previous=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));assertTrue(store.isActive(previous));app=pair();Capability next=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));assertFalse(store.isActive(previous));assertTrue(store.isActive(next));}
    @Test void explicitLogoutAtomicallyRevokesAllApplications(){Capability core=cap(App.AEGIS,EnumSet.of(Scope.SESSION_MANAGE));String n=IdentityProtocol.nonce();byte[] proof=IdentityProtocol.sign(app.getPrivate(),IdentityProtocol.request(core,"session.manage",new byte[0],clock.millis(),n));store.revoke(core,clock.millis(),n,proof);assertFalse(store.isActive(core));assertThrows(IdentityException.class,()->cap(App.AEGIS,EnumSet.of(Scope.ACCOUNT_READ)));}
    @Test void auditTailTruncationWithoutChangingAnchorIsDetected()throws Exception {store.close();try(java.sql.Connection sql=java.sql.DriverManager.getConnection("jdbc:sqlite:"+home.resolve("identity.db"));java.sql.Statement st=sql.createStatement()){st.executeUpdate("DELETE FROM audit");}assertThrows(IdentityException.class,()->new IdentityStore(home.resolve("identity.db"),service,audit,clock));store=new IdentityStore(home.resolve("new-after-truncation.db"),service,audit,clock);}
    @Test void applicationAndDeviceKeysCannotBeReusedAcrossDifferentAccounts()throws Exception {Capability first=cap(App.MAIL,EnumSet.of(Scope.MAIL_READ));KeyPair anotherRoot=pair(),anotherDevice=pair(),anotherRecovery=pair();IdentityStore.Session second=register(anotherRoot,anotherDevice,anotherRecovery);String nonce=IdentityProtocol.nonce();byte[] body=IdentityProtocol.capabilityRequest(store.audience(),second.accountId(),second.deviceId(),second.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),nonce);assertThrows(IdentityException.class,()->store.issueCapability(second.accountId(),second.deviceId(),second.generation(),App.MAIL,key(app),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),nonce,IdentityProtocol.sign(anotherDevice.getPrivate(),body),IdentityProtocol.sign(app.getPrivate(),body)));String n=IdentityProtocol.nonce();byte[] asApp=IdentityProtocol.capabilityRequest(store.audience(),second.accountId(),second.deviceId(),second.generation(),App.MAIL,key(device),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n);assertThrows(IdentityException.class,()->store.issueCapability(second.accountId(),second.deviceId(),second.generation(),App.MAIL,key(device),EnumSet.of(Scope.MAIL_READ),1000,clock.millis(),n,IdentityProtocol.sign(anotherDevice.getPrivate(),asApp),IdentityProtocol.sign(device.getPrivate(),asApp)));assertThrows(IdentityException.class,()->register(pair(),device,pair()));assertTrue(store.isActive(first));}
    @Test void managedAccountQueryRequiresSeparateOperatorPinnedRelayProofAndOneUseNonce()throws Exception {KeyPair relay=pair(),stranger=pair();String relayId=IdentityProtocol.id(key(relay)),nonce=IdentityProtocol.nonce();byte[] query=IdentityProtocol.managedAccountQuery(store.audience(),relayId,account,clock.millis(),nonce),proof=IdentityProtocol.sign(relay.getPrivate(),query);assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,clock.millis(),nonce,proof));assertThrows(IdentityException.class,()->store.allowRelayService(key(relay),IdentityProtocol.id(key(stranger))));store.allowRelayService(key(relay),relayId);assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,clock.millis(),nonce,IdentityProtocol.sign(stranger.getPrivate(),query)));assertTrue(store.managedAccount(key(relay),account,clock.millis(),nonce,proof));assertEquals("REPLAY",assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,clock.millis(),nonce,proof)).code());String missing=IdentityProtocol.id(key(stranger)),n=IdentityProtocol.nonce();assertFalse(store.managedAccount(key(relay),missing,clock.millis(),n,IdentityProtocol.sign(relay.getPrivate(),IdentityProtocol.managedAccountQuery(store.audience(),relayId,missing,clock.millis(),n))));assertThrows(IdentityException.class,()->store.allowRelayService(key(device),deviceId));assertThrows(IdentityException.class,()->register(pair(),relay,pair()));store.revokeRelayService(relayId);String next=IdentityProtocol.nonce();assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,clock.millis(),next,IdentityProtocol.sign(relay.getPrivate(),IdentityProtocol.managedAccountQuery(store.audience(),relayId,account,clock.millis(),next))));assertTrue(store.verifyAudit());}
    @Test void managedAccountQueryRejectsWrongServicePurposeExpiryAndClockRollback()throws Exception {KeyPair relay=pair();String id=IdentityProtocol.id(key(relay));store.allowRelayService(key(relay),id);String n=IdentityProtocol.nonce();long t=clock.millis();byte[] wrong=IdentityProtocol.managedAccountQuery(IdentityProtocol.id(key(pair())),id,account,t,n);assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,t,n,IdentityProtocol.sign(relay.getPrivate(),wrong)));clock.value+=60001;byte[] expired=IdentityProtocol.managedAccountQuery(store.audience(),id,account,t,n);assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,t,n,IdentityProtocol.sign(relay.getPrivate(),expired)));String fresh=IdentityProtocol.nonce();assertTrue(store.managedAccount(key(relay),account,clock.millis(),fresh,IdentityProtocol.sign(relay.getPrivate(),IdentityProtocol.managedAccountQuery(store.audience(),id,account,clock.millis(),fresh))));clock.value--;String rollback=IdentityProtocol.nonce();assertEquals("CLOCK_ROLLBACK",assertThrows(IdentityException.class,()->store.managedAccount(key(relay),account,clock.millis(),rollback,IdentityProtocol.sign(relay.getPrivate(),IdentityProtocol.managedAccountQuery(store.audience(),id,account,clock.millis(),rollback)))).code());}
    static final class MutableClock extends Clock {long value=1_800_000_000_000L;public ZoneId getZone(){return ZoneOffset.UTC;}public Clock withZone(ZoneId z){return this;}public Instant instant(){return Instant.ofEpochMilli(value);}public long millis(){return value;}}
}
